INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Income Tax Filing', 'income-tax-filing', 'Understand how small businesses generally file annual income tax returns online.', 'Income Tax Filing refers to the process of formally reporting a business''s income, expenses, and applicable deductions to the tax authority for a financial year. It establishes a documented record of earnings and tax liability.', 'Filing an income tax return helps a business stay compliant with tax law, claim eligible deductions, carry forward losses where applicable, and maintain financial credibility for loans or tenders.', 'Businesses and individuals whose income exceeds the applicable exemption threshold, or who are otherwise required by law to file, generally need to file an income tax return. Specific applicability depends on business structure and turnover.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax Department e-Filing Portal', 'https://www.incometax.gov.in/', 'Keep all income and expense records ready before starting. Cross-check pre-filled data on the portal against your own books. Common mistakes include mismatched income figures, missing deduction proofs, and late filing. Official portal link to be verified/confirmed before deployment.', 'After submission, an acknowledgement (ITR-V or equivalent) is generated. Retain this for your records and complete e-verification within the allowed window to complete the filing process.', 'services/income-tax/income-tax_intro.png', 'services/income-tax/income-tax_step_01.png', 'services/income-tax/income-tax_complete.png', 1);
