INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Open the official portal', 'Visit the Income Tax Department e-filing portal using the official URL only.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Login or Register', 'Log in using your PAN-linked credentials, or register if you are a first-time user.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Select the relevant filing option', 'Choose the appropriate income tax return form based on your business category.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Enter required information', 'Fill in income, expense, and deduction details accurately based on your records.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Upload applicable documents', 'Attach supporting statements where the portal allows or requests them.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Review information', 'Carefully review all entered figures before proceeding to submission.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Submit and verify', 'Submit the return and complete e-verification through the available method.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Save acknowledgement', 'Download and store the acknowledgement/reference number safely.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Income Tax', 'Do I need to file if my business made a loss?', 'In many cases, filing is still recommended to carry forward losses, but applicability depends on your specific situation. Confirm with a tax professional or the official portal guidance.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Income Tax', 'What happens if I file late?', 'Late filing may attract fees or interest as prescribed by tax law. Check current provisions on the official portal.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('GST Registration', 'gst-registration', 'Learn the general process for registering a business under GST.', 'GST Registration is the process by which a business obtains a unique GST Identification Number (GSTIN), enabling it to legally collect and remit Goods and Services Tax.', 'Registration allows a business to issue valid GST invoices, claim input tax credit, and operate legally where GST registration is applicable.', 'Businesses exceeding the prescribed turnover threshold, or engaged in specific categories of supply, are generally required to register. Thresholds and categories vary, so verify applicability for your business type.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'GST Portal', 'https://www.gst.gov.in/', 'Ensure business address proof and bank details are accurate, as mismatches are a common reason for delays. Keep scanned copies of documents ready in the required format. Official portal link to be verified/confirmed before deployment.', 'Once approved, a GSTIN certificate is issued. Display your GSTIN on invoices and at your place of business as required by law.', 'services/gst-registration/gst-registration_intro.png', 'services/gst-registration/gst-registration_step_01.png', 'services/gst-registration/gst-registration_complete.png', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'PAN card of business/proprietor', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Business address proof', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Bank account details', 3);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Identity proof of proprietor/partners/directors', 4);
