INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Generate a Temporary Reference Number (TRN)', 'Start a new registration application using basic details like PAN and mobile number.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Complete the application form', 'Fill in business details, promoter/partner information, and place of business.');
