INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Verify using OTP/DSC', 'Complete identity verification through the method applicable to your entity type.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Review application', 'Recheck all sections before final submission.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Submit application', 'Submit and note the Application Reference Number (ARN).');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Track and save certificate', 'Track status using the ARN and download the GST certificate once approved.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'GST', 'Is GST registration mandatory for every business?', 'No. It depends on turnover and the nature of supply. Verify applicability for your specific business on the official portal.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'GST', 'How long does registration usually take?', 'Processing times vary. Refer to the official portal for current estimated timelines.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('GST Return Filing', 'gst-return-filing', 'Understand the general process of filing periodic GST returns.', 'GST Return Filing is the periodic process of reporting sales, purchases, and tax collected/paid to the GST authorities, based on your registration category.', 'Regular return filing keeps your GST registration compliant, supports input tax credit claims, and avoids penalties for non-filing.', 'Any business registered under GST is generally required to file returns as per the frequency applicable to their registration type.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'GST Portal', 'https://www.gst.gov.in/', 'Reconcile your sales and purchase records with auto-populated data before filing. Common mistakes include mismatched invoice details and missed filing deadlines. Official portal link to be verified/confirmed before deployment.', 'Once filed, an Acknowledgement Reference Number (ARN) is generated. Retain this along with the filed return copy for your records.', 'services/gst-return-filing/gst-return-filing_intro.png', 'services/gst-return-filing/gst-return-filing_step_01.png', 'services/gst-return-filing/gst-return-filing_complete.png', 3);
