INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'GST', 'What if I miss a filing deadline?', 'Late fees and interest may apply as per current GST law. Check the official portal for applicable rates.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'GST', 'Can I revise a filed return?', 'Correction mechanisms vary by return type. Refer to official GST guidance for your specific case.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('GST Invoice & E-Invoicing', 'gst-invoice-and-e-invoicing', 'Understand GST-compliant invoicing and e-invoicing requirements.', 'GST Invoicing involves issuing invoices that meet prescribed format requirements, while e-Invoicing is a system where certain businesses must generate invoices through a government-notified portal for authentication.', 'Proper invoicing ensures your transactions are legally valid, supports accurate return filing, and enables customers to claim input tax credit.', 'Standard GST invoicing rules apply to all registered businesses. E-invoicing applicability depends on turnover thresholds notified by the authorities from time to time.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'GST e-Invoice Portal', 'https://einvoice1.gst.gov.in/', 'Ensure invoice fields such as GSTIN, HSN/SAC codes, and tax breakup are accurate. For e-invoicing, generate the Invoice Reference Number (IRN) before sharing the invoice with the customer. Official portal link to be verified/confirmed before deployment.', 'A valid e-invoice includes a QR code and IRN issued by the government system. Retain these records for compliance and audit purposes.', 'services/gst-invoice/gst-invoice_intro.png', 'services/gst-invoice/gst-invoice_step_01.png', 'services/gst-invoice/gst-invoice_complete.png', 4);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'GSTIN details', 1);
