INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'GST', 'What is an IRN?', 'An Invoice Reference Number is a unique identifier generated by the government system for each valid e-invoice.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('TDS Filing', 'tds-filing', 'Understand the process of filing Tax Deducted at Source (TDS) returns.', 'TDS Filing is the process of reporting tax deducted at source on specified payments, such as salaries or contractor payments, to the tax authorities on a periodic basis.', 'Filing TDS returns ensures deducted tax is properly credited to the payee''s account and keeps the deductor compliant with withholding tax obligations.', 'Businesses that are required to deduct tax at source on applicable payments generally need to file periodic TDS returns.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'TRACES / Income Tax e-Filing Portal', 'https://www.tdscpc.gov.in/', 'Ensure deductee PAN details are accurate, as incorrect PAN entries are a common cause of return rejection or credit mismatches. Official portal link to be verified/confirmed before deployment.', 'After filing, a provisional receipt is generated. TDS certificates (such as Form 16/16A equivalents) should be issued to deductees as applicable.', 'services/tds-filing/tds-filling1.png', 'services/tds-filing/tds-filling2.png', 'services/tds-filing/tds-filling3.png', 5);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'TAN details', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Deductee PAN details', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Payment and deduction records', 3);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Challan details for tax deposited', 4);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Previous return filing acknowledgment', 5);
