INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Retain records', 'Store filing records and challans for future reference.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'TDS', 'What happens if TDS is deducted but not deposited on time?', 'Interest and penalties may apply as per applicable law. Verify current provisions on the official portal.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('TDS Payment', 'tds-payment', 'Understand how deducted TDS amounts are generally deposited with the government.', 'TDS Payment refers to depositing the tax amount deducted at source with the government within the prescribed timeline, using an authorized payment channel.', 'Timely deposit of deducted tax avoids interest and penalty, and ensures deductees receive proper credit for the tax withheld on their behalf.', 'Any business or individual who has deducted TDS on applicable payments is generally required to deposit the deducted amount.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'e-Pay Tax (Income Tax Portal)', 'https://www.incometax.gov.in/', 'Select the correct assessment year, payment code, and TAN before making payment. Errors in these fields are a common source of mismatched credit. Official portal link to be verified/confirmed before deployment.', 'A challan with a unique identification number is generated after successful payment. Retain this for reconciliation with your TDS return.', 'services/tds-payment/tds-payment1.png', 'services/tds-payment/tds-payment2.png', 'services/tds-payment/tsd-payment3.png', 6);
