INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Payments', 'What if I select the wrong assessment year?', 'Correction mechanisms exist but vary by process. Refer to official guidance to correct challan details.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Advance Tax Payment', 'advance-tax-payment', 'Understand the general concept of paying advance tax in instalments.', 'Advance Tax is income tax paid in advance in instalments during the financial year, rather than as a lump sum at the end of the year, where applicable.', 'Paying advance tax on time helps avoid interest charges that may apply for deferred or short payment of tax liability.', 'Businesses and individuals whose estimated tax liability exceeds the prescribed threshold for the year are generally required to pay advance tax.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'e-Pay Tax (Income Tax Portal)', 'https://www.incometax.gov.in/', 'Estimate your income for the year as accurately as possible. Significant underestimation may lead to interest liability. Review your estimate each instalment period. Official portal link to be verified/confirmed before deployment.', 'A challan is generated for each instalment paid. Retain all challans, as they will be needed when filing your annual income tax return.', 'services/advance-tax/advance-tax_intro.png', 'services/advance-tax/advance-tax_step_01.png', 'services/advance-tax/advance-tax_complete.png', 7);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'PAN', 1);
