INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Payments', 'What if my estimated income changes during the year?', 'You can generally adjust subsequent instalments based on revised estimates. Refer to official guidance for details.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Tax Payment & Challan', 'tax-payment-and-challan', 'Understand the general process for making tax payments and generating challans.', 'Tax Payment & Challan covers the general process of depositing various types of tax dues through the official portal and obtaining proof of payment.', 'A valid challan serves as legal proof of tax payment and is required when filing returns or responding to tax notices.', 'Any taxpayer with an outstanding tax liability, of any applicable category, may need to make a payment through this process.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'e-Pay Tax (Income Tax Portal)', 'https://www.incometax.gov.in/', 'Double-check the payment category and assessment year before submitting payment, as these determine how the payment is credited. Official portal link to be verified/confirmed before deployment.', 'Save the generated challan receipt immediately after payment. It may not always be easy to retrieve later, so keep a personal copy.', 'services/tax-payment-challan/tax-payment1.png', 'services/tax-payment-challan/tax-payment2.png', 'services/tax-payment-challan/tax-payment3.png', 8);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'PAN/TAN as applicable', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Assessment year', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Payment category/type', 3);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Bank account details', 4);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Open the payment portal', 'Navigate to the official tax payment section.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Select payment type', 'Choose the correct category of tax being paid.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Enter identification details', 'Provide PAN/TAN and relevant assessment year.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Enter payment amount', 'Fill in the correct breakup of tax, interest, and penalty if applicable.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Select payment method', 'Choose from the available secure payment options.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Authorize payment', 'Complete the transaction through your bank''s verification process.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Download challan', 'Save the challan with its unique reference number.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Retain for records', 'Store the challan safely for use in filings or future reference.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Payments', 'What should I do if payment is deducted but no challan is generated?', 'Wait for confirmation, check your bank statement, and contact official support channels if the issue persists.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Tax Deduction & Exemptions', 'tax-deduction-and-exemptions', 'Understand the general concept of deductions and exemptions available to businesses.', 'Tax Deductions and Exemptions are provisions that allow eligible expenses, investments, or categories of income to reduce overall taxable income, subject to conditions.', 'Understanding applicable deductions helps a business plan finances and legally reduce tax liability within the framework of the law.', 'Eligibility for specific deductions or exemptions depends on business type, nature of expense, and category of income. Verify applicability carefully.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax Department Portal', 'https://www.incometax.gov.in/', 'Maintain proper documentary evidence for every deduction claimed. Claims without supporting proof are a common reason for scrutiny. Official portal link to be verified/confirmed before deployment.', 'Deductions and exemptions are reflected in your income tax computation at the time of filing. Retain supporting documents even after filing.', 'services/tax-deduction/tax-deducation1.png', 'services/tax-deduction/tax-deducation2.png', 'services/tax-deduction/tax-deducation3.png', 9);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Investment proofs', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Expense receipts', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Business asset records', 3);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Loan/interest certificates (if applicable)', 4);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Insurance/other eligible payment proofs', 5);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Identify applicable provisions', 'Review which deductions or exemptions may apply to your business category.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Collect supporting documents', 'Gather receipts, certificates, and proofs for each claim.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Organize records by category', 'Sort documentation to match the relevant deduction heads.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Enter details during filing', 'Reflect eligible deductions accurately in your income tax return.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Cross-check computation', 'Verify that deductions are correctly reducing your taxable income.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Retain proofs', 'Keep all supporting documents safely even after submission.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Review for next year', 'Reassess your eligible deductions periodically as your business grows.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Consult a professional if unsure', 'For complex situations, consider professional guidance to avoid errors.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Income Tax', 'Can every business expense be claimed as a deduction?', 'No. Only expenses meeting specific criteria under applicable law can be claimed. Verify each category carefully.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Income & Expense Record Keeping', 'income-and-expense-record-keeping', 'Understand good practices for maintaining income and expense records.', 'Income & Expense Record Keeping refers to systematically maintaining financial records of a business''s earnings and expenditures for compliance and decision-making.', 'Accurate record keeping supports correct tax filing, simplifies audits, and provides a clear financial picture for business planning.', 'All businesses, regardless of size, benefit from maintaining organized income and expense records. Certain categories may be legally required to do so.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax Department Portal', 'https://www.incometax.gov.in/', 'Keep records updated regularly rather than at year-end. Reconcile bank statements with your books periodically to catch errors early. Official portal link to be verified/confirmed before deployment.', 'Well-maintained records make annual filing significantly smoother and reduce the risk of errors or missed deductions.', 'services/income-expense/income-expense_intro.png', 'services/income-expense/income-expense_step_01.png', 'services/income-expense/income-expense_complete.png', 10);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Sales invoices', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Purchase bills', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Bank statements', 3);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Cash records', 4);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Payroll records (if applicable)', 5);
