INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Choose a record-keeping method', 'Decide between manual registers, spreadsheets, or accounting software.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Record transactions regularly', 'Log income and expenses as they occur rather than in bulk later.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Categorize expenses', 'Group expenses under consistent categories for easier analysis.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Reconcile with bank statements', 'Match recorded transactions against actual bank activity periodically.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Back up records', 'Maintain secure digital or physical backups of financial records.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Review monthly summaries', 'Check periodic summaries to track business performance.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Prepare for filing season', 'Compile annual summaries ahead of tax filing deadlines.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Retain records long-term', 'Keep records for the legally prescribed retention period.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Documents', 'How long should I keep financial records?', 'Retention periods vary by document type and applicable law. Check current requirements or consult a professional.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Tax Document Management', 'tax-document-management', 'Understand how to organize and manage tax-related documents.', 'Tax Document Management involves systematically organizing, storing, and retrieving documents required for tax compliance, filings, and potential audits.', 'Proper document management reduces stress during filing season and ensures you can respond quickly to any tax notice or verification request.', 'Applicable to any business that files taxes, maintains GST records, or is otherwise subject to tax compliance requirements.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax Department Portal', 'https://www.incometax.gov.in/', 'Organize documents by financial year and category. Keep both digital and physical copies where feasible, and ensure backups are secure. Official portal link to be verified/confirmed before deployment.', 'A well-organized document system allows quick access during filing, audits, or when responding to official queries.', 'services/tax-document-management/tax-document1.png', 'services/tax-document-management/tax-document2.png', 'services/tax-document-management/tax-document3.png', 11);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'PAN/TAN/GSTIN copies', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Filed return copies', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Payment challans', 3);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Invoices and bills', 4);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Bank statements', 5);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Prior year assessment records', 6);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Create a folder structure', 'Set up folders by financial year and document category.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Digitize physical documents', 'Scan paper documents for secure digital storage.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Label files clearly', 'Use consistent, descriptive file names for easy retrieval.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Store securely', 'Use password-protected or access-controlled storage where possible.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Maintain backups', 'Keep at least one additional backup copy in a separate location.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Review periodically', 'Check your document set quarterly to ensure completeness.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Prepare for filing', 'Compile the relevant documents before each filing deadline.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Retain per requirement', 'Keep documents for the legally prescribed retention period.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Documents', 'Should I keep digital copies or originals?', 'Both are useful. Digital copies aid quick access; originals may still be required for certain verifications.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Tax Calendar & Due Dates', 'tax-calendar-and-due-dates', 'Understand how to track important tax-related due dates.', 'The Tax Calendar helps businesses track important filing and payment due dates across income tax, GST, and TDS obligations.', 'Tracking due dates helps avoid late fees, interest, and compliance issues that arise from missed deadlines.', 'Relevant to any business that has ongoing tax filing or payment obligations of any applicable category.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax Department / GST Portal', 'https://www.incometax.gov.in/', 'Due dates can change based on official notifications. Always confirm the current due date on the relevant official portal before the deadline. Official portal link to be verified/confirmed before deployment.', 'Maintaining a personal or business tax calendar, cross-checked against official announcements, helps ensure consistent compliance.', 'services/tax-calendar/tax-calendar_intro.png', 'services/tax-calendar/tax-calendar_step_01.png', 'services/tax-calendar/tax-calendar_complete.png', 12);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'List of applicable tax obligations', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Registration details (PAN/TAN/GSTIN)', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Previous compliance history', 3);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'List applicable obligations', 'Identify every tax filing or payment relevant to your business.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Check official due dates', 'Refer to the official portal for the current schedule.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Set reminders', 'Use calendar reminders ahead of each due date.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Prepare documents in advance', 'Gather required information before the deadline approaches.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Monitor for notifications', 'Watch for official updates that may shift due dates.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Complete filing/payment on time', 'Submit filings or payments within the applicable window.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Record completion', 'Note completed obligations to track your compliance history.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Review calendar periodically', 'Update your tracking system as your business obligations change.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Documents', 'Do due dates ever get extended?', 'Occasionally, authorities may extend deadlines. Always check official announcements rather than assuming an extension.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Tax Refund Status', 'tax-refund-status', 'Understand how to generally track the status of a tax refund.', 'Tax Refund Status tracking allows a taxpayer to check the progress of a refund due after excess tax has been paid or deducted.', 'Tracking refund status helps you know when to expect funds and identify any issues that may need follow-up action.', 'Applicable to any taxpayer who has filed a return resulting in a refund due, based on excess tax paid or deducted.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax e-Filing Portal', 'https://www.incometax.gov.in/', 'Ensure your bank account is validated and linked correctly on the portal, as this is a common reason for refund delays. Official portal link to be verified/confirmed before deployment.', 'Once processed, the refund is credited directly to your validated bank account. Retain the refund confirmation for your records.', 'services/tax-refund/tax-refund1.png', 'services/tax-refund/tax-refund2.png', 'services/tax-refund/tax-refund3.png', 13);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'PAN', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Filed return acknowledgment', 2);
