INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Assessment year reference', 4);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Log in to the official portal', 'Access your account using your PAN-linked credentials.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Navigate to refund status', 'Find the refund tracking section within the portal.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Enter relevant details', 'Provide the assessment year and any requested reference numbers.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Check current status', 'Review the displayed processing stage of your refund.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Verify bank details if prompted', 'Ensure your bank account is validated if the portal flags an issue.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Note any discrepancies', 'Record any mismatches for follow-up with official support.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Wait for credit confirmation', 'Refunds are typically credited after processing is complete.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Retain confirmation', 'Save the refund credit confirmation for your financial records.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Income Tax', 'Why is my refund delayed?', 'Delays can occur due to bank validation issues, return scrutiny, or processing backlogs. Check official status updates for details.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Tax Notice & Compliance Guidance', 'tax-notice-and-compliance-guidance', 'Understand general guidance on responding to tax notices.', 'A Tax Notice is official communication from the tax authority regarding discrepancies, clarifications, or compliance requirements related to your filings.', 'Understanding how to respond to a notice helps ensure timely compliance and reduces the risk of further escalation.', 'Relevant to any taxpayer who has received an official notice or communication from the tax department.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax e-Filing Portal', 'https://www.incometax.gov.in/', 'Always verify that a notice is genuine by checking it through the official portal. Do not respond to suspicious emails or calls claiming to be tax authorities requesting sensitive information. Official portal link to be verified/confirmed before deployment.', 'Responding within the specified timeline through official channels helps resolve most notices smoothly. Keep a copy of your response and any related correspondence.', 'services/tax-notice/tax-notice1.png', 'services/tax-notice/tax-notice2.png', 'services/tax-notice/tax-notice3.png', 14);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Copy of the notice', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Related filed return', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Supporting documents relevant to the notice', 3);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Prior correspondence (if any)', 4);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Verify the notice', 'Confirm authenticity by logging into the official portal directly, not through links in emails.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Read the notice carefully', 'Understand exactly what clarification or action is being requested.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Gather relevant documents', 'Compile records that support your position or clarify the discrepancy.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Draft your response', 'Prepare a clear, factual response addressing each point raised.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Submit through official channels', 'Respond using the designated portal section, not external communication.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Track acknowledgment', 'Confirm your response has been recorded successfully.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Follow up if needed', 'Monitor for further communication or requests for clarification.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Retain records', 'Keep copies of the notice and your response for future reference.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Income Tax', 'How do I know if a notice is genuine?', 'Always verify directly through the official portal rather than trusting links, calls, or messages claiming urgency.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('PAN Services', 'pan-services', 'Understand the general process for PAN-related services.', 'PAN (Permanent Account Number) Services cover processes such as applying for a new PAN, updating details, or reprinting a PAN card.', 'A valid PAN is required for most financial and tax-related transactions, including filing returns and opening business bank accounts.', 'Applicable to businesses and individuals who need to apply for, update, or reissue a PAN.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Protean (NSDL) / UTIITSL PAN Services Portal', 'https://www.protean-tinpan.com/', 'Ensure the name and details entered match your official identity documents exactly, as mismatches can delay processing. Official portal link to be verified/confirmed before deployment.', 'Once processed, the PAN card is issued physically and/or digitally, depending on the option selected during application.', 'services/pan-services/pan-services_intro.png', 'services/pan-services/pan-services_step_01.png', 'services/pan-services/pan-services_complete.png', 15);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Identity proof', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Address proof', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Date of birth proof', 3);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Business registration proof (for entities)', 4);
