INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Open the official PAN services portal', 'Navigate to the appropriate application section.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Choose the applicable service', 'Select new application, correction, or reprint as needed.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Fill in the application form', 'Enter details exactly as per your supporting documents.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Upload required documents', 'Attach scanned proofs in the specified format.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Make the applicable payment', 'Pay the prescribed fee through the available payment methods.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Complete verification', 'Verify using the applicable method (e-KYC, DSC, or physical submission).');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Track application status', 'Use the acknowledgment number to monitor progress.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Receive PAN card', 'Collect the physical card and/or download the e-PAN once issued.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Documents', 'Can I apply for PAN correction online?', 'Yes, correction requests can generally be submitted online through the official portal.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('TAN Services', 'tan-services', 'Understand the general process for TAN-related services.', 'TAN (Tax Deduction and Collection Account Number) Services cover applying for or updating the number required by entities that deduct or collect tax at source.', 'A valid TAN is mandatory for any business responsible for deducting TDS, and is required when filing TDS returns.', 'Applicable to businesses or individuals who are required to deduct or collect tax at source.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Protean (NSDL) TAN Services Portal', 'https://www.protean-tinpan.com/', 'Double-check business name and address details before submission, as these appear on the official TAN allotment letter. Official portal link to be verified/confirmed before deployment.', 'Once allotted, the TAN should be used consistently across all TDS-related filings and payments.', 'services/tan-services/tan-services_intro.png', 'services/tan-services/tan-services_step_01.png', 'services/tan-services/tan-services_complete.png', 16);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Business registration proof', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Identity proof of applicant', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Address proof of business', 3);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Existing PAN of the business (if applicable)', 4);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Open the official TAN application portal', 'Navigate to the new TAN application section.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Select applicant category', 'Choose the category matching your business structure.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Fill in application details', 'Provide accurate business and contact information.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Upload or submit documents', 'Provide required proofs as per the selected submission method.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Pay the applicable fee', 'Complete payment through the available methods.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Submit the application', 'Confirm and submit the completed form.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Track status', 'Use the acknowledgment number to check processing status.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Receive TAN allotment letter', 'Save the letter once TAN is allotted.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Documents', 'Does every business need a TAN?', 'Only businesses required to deduct or collect tax at source generally need a TAN. Verify applicability for your case.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Business Tax Registration', 'business-tax-registration', 'Understand general registration requirements for a new business from a tax perspective.', 'Business Tax Registration covers the various registrations a new business may need, such as PAN, TAN, GST, and other applicable licenses, from a tax compliance standpoint.', 'Proper registration at the start of a business ensures smooth tax compliance and avoids penalties for operating without required registrations.', 'Applicable to anyone starting a new business who needs to determine which tax registrations apply to their business type and turnover.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax / GST Portal', 'https://www.incometax.gov.in/', 'Registration requirements vary by business structure (proprietorship, partnership, company, etc.) and turnover. Confirm the exact requirements applicable to your business before proceeding. Official portal link to be verified/confirmed before deployment.', 'Once all applicable registrations are complete, maintain the certificates and numbers together for easy reference during compliance activities.', 'services/business-tax-registration/business-tax-registration_intro.png', 'services/business-tax-registration/business-tax-registration_step_01.png', 'services/business-tax-registration/business-tax-registration_complete.png', 17);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Business structure documents', 1);
