INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Bank account details', 4);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Determine applicable registrations', 'Identify which tax registrations (PAN, TAN, GST, etc.) apply to your business.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Gather common documents', 'Compile identity, address, and business proofs needed across registrations.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Apply for PAN', 'Complete PAN application if not already obtained.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Apply for TAN if applicable', 'Register for TAN if your business will deduct tax at source.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Apply for GST if applicable', 'Complete GST registration if turnover or business type requires it.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Track each application', 'Monitor status across all submitted registrations.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Collect certificates', 'Save all issued registration certificates and numbers.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Set up compliance calendar', 'Note ongoing filing obligations tied to each registration.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Documents', 'Do I need GST registration from day one?', 'Not necessarily — it depends on your turnover and business category. Verify current thresholds on the official portal.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Tax Compliance Checklist', 'tax-compliance-checklist', 'Understand a general checklist approach to ongoing tax compliance.', 'A Tax Compliance Checklist helps a business track recurring obligations across income tax, GST, and TDS to reduce the risk of missed deadlines or filings.', 'Using a checklist approach improves consistency in compliance and provides a quick reference during audits or reviews.', 'Useful for any business seeking a structured way to track its ongoing tax obligations.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax / GST Portal', 'https://www.incometax.gov.in/', 'A checklist is a planning aid, not a substitute for professional advice. Requirements vary by business and should be verified individually. Official portal link to be verified/confirmed before deployment.', 'Review and update your compliance checklist periodically as regulations or your business circumstances change.', 'services/tax-compliance/tax-compliance_intro.png', 'services/tax-compliance/tax-compliance_step_01.png', 'services/tax-compliance/tax-compliance_complete.png', 18);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'List of applicable registrations (PAN/TAN/GSTIN)', 1);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Filing history', 2);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'Previous compliance records', 3);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'List all applicable obligations', 'Identify every recurring tax filing or payment relevant to your business.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Assign due dates', 'Map each obligation to its applicable due date.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Assign responsibility', 'Note who within the business is responsible for each item.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Track document readiness', 'Confirm supporting documents are prepared ahead of each deadline.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Mark completion status', 'Update the checklist as each obligation is completed.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Review for missed items', 'Periodically audit the checklist for gaps.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Update for regulatory changes', 'Revise the checklist when rules or thresholds change.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Retain historical checklists', 'Keep past checklists as a reference for future periods.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Documents', 'Can this checklist replace professional advice?', 'No. It is a general planning aid. For specific situations, consult a qualified tax professional.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Tax FAQs & Help', 'tax-faqs-and-help', 'A general help section answering common tax-related questions.', 'The Tax FAQs & Help section brings together commonly asked questions from small business owners about digital tax processes.', 'This section helps clarify frequently misunderstood aspects of tax filing and compliance in a simple, accessible format.', 'Open to all users of the platform seeking general clarification on tax-related topics.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax Department Portal', 'https://www.incometax.gov.in/', 'FAQ answers are general in nature and may not cover every specific circumstance. For complex or unusual situations, consult a tax professional or the official portal. Official portal link to be verified/confirmed before deployment.', 'If your question is not answered here, use the Contact form to reach out for more information.', 'services/tax-faq/tax-faq1.png', 'services/tax-faq/tax-faq2.png', 'services/tax-faq/tax-faq3.png', 19);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'No specific documents required to browse this section', 1);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Browse by category', 'Use categories such as Income Tax, GST, TDS, or Payments to find relevant questions.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Search for keywords', 'Use the search function to quickly locate a specific topic.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Read the full answer', 'Expand the FAQ to read the complete explanation.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Check related services', 'Visit the related service guide for more in-depth information.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Verify on official portal', 'Cross-check important details on the relevant official government portal.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Use the contact form', 'Reach out through the Contact page if your question remains unanswered.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Provide feedback', 'Let us know if an FAQ was unclear so it can be improved.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Return as needed', 'Revisit this section whenever new questions arise.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'FAQs', 'Is this platform an official government service?', 'No. This platform provides general guidance only. All actual filing and payment should be done through the official government portal.');
INSERT INTO services (name, slug, short_description, introduction, purpose, eligibility, charges, official_portal_name, official_portal_url, important_information, final_information, intro_image, middle_image, final_image, display_order) VALUES ('Tax Safety & Fraud Awareness', 'tax-safety-and-fraud-awareness', 'Understand common digital safety precautions related to tax processes.', 'Tax Safety & Fraud Awareness covers precautions to protect yourself from fraudulent websites, phishing attempts, and scams related to tax filing and payments.', 'Awareness of common fraud tactics helps protect your financial information and prevents unauthorized transactions.', 'Relevant to every user who interacts with digital tax or financial services.', 'Fees may vary depending on the applicable service/process, filing category, and business circumstances. Please verify the current applicable amount on the official portal before proceeding.', 'Income Tax Department Portal', 'https://www.incometax.gov.in/', 'Never share your OTP, passwords, or PINs with anyone, including anyone claiming to represent a tax department or this platform. Always verify official portal URLs directly. Official portal link to be verified/confirmed before deployment.', 'When in doubt about the authenticity of a message, call, or website, do not proceed. Verify independently using official contact information.', 'services/tax-safety/tax-safety1.png', 'services/tax-safety/tax-safety2.png', 'services/tax-safety/tax-safety3.png', 20);
INSERT INTO service_documents (service_id, document_name, display_order) VALUES (@svc_id, 'No specific documents required for this section', 1);
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 1, 'Verify the official URL', 'Always type or bookmark the official portal address directly rather than clicking links from messages.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 2, 'Check for secure connection indicators', 'Look for standard browser security indicators before entering information.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 3, 'Never share OTPs or PINs', 'No legitimate authority will ask you to share an OTP or PIN over call or message.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 4, 'Be cautious with unsolicited messages', 'Treat unexpected emails, SMS, or calls about refunds or dues with caution.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 5, 'Avoid suspicious attachments/links', 'Do not open attachments or links from unverified sources.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 6, 'Use secure networks', 'Avoid conducting tax transactions over public or unsecured Wi-Fi.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 7, 'Report suspicious activity', 'Report phishing attempts through official channels.');
INSERT INTO service_steps (service_id, step_number, step_title, step_description) VALUES (@svc_id, 8, 'Stay informed', 'Periodically review official advisories about known scam patterns.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (@svc_id, 'Safety', 'Will this platform ever ask for my OTP or password?', 'No. This platform never asks for OTPs, portal passwords, bank passwords, UPI PINs, or card PINs.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (NULL, 'Safety', 'Does this platform store my OTP or passwords?', 'No. This platform never collects OTPs, government portal passwords, bank passwords, UPI PINs, or card PINs.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (NULL, 'Income Tax', 'Is this platform an official government portal?', 'No. This platform is an awareness and guidance tool. All actual filing and payment must be completed on the relevant official government portal.');
INSERT INTO service_faqs (service_id, category, question, answer) VALUES (NULL, 'Documents', 'Where can I see all documents required for a service?', 'Each service detail page includes a Documents/Information Required checklist specific to that service.');
